# Find max clique size
# Using a simple recursive approach with backtracking.
def max_clique_size(G):
    max_clique = []

    def backtrack(candidates, current_clique):
        nonlocal max_clique
        if not candidates:
            if len(current_clique) > len(max_clique):
                max_clique = list(current_clique)
            return

        if len(current_clique) + len(candidates) <= len(max_clique):
            return

        v = candidates[0]
        # Try including v
        new_candidates = [c for c in candidates[1:] if G.has_edge(v, c)]
        backtrack(new_candidates, current_clique + [v])

        # Try excluding v
        backtrack(candidates[1:], current_clique)

    nodes = sorted(list(G.nodes()))
    backtrack(nodes, [])
    return len(max_clique)

