def find_max_clique_size(max_k):
    G = nx.Graph()
    for k1 in range(1, max_k):
        for k2 in range(k1 + 1, max_k):
            if L(k1) < R(k2) and L(k2) < R(k1):
                G.add_edge(k1, k2)

    # Use a more efficient clique finder
    # For a small number of nodes, we can use the Bron-Kerbosch algorithm
    # which is available in networkx as something? No, but let's just use a simple one.

    # Actually, let's use the property of interval graphs.
    # For an interval graph, the maximum clique size is the maximum number of 
    # intervals that overlap at a single point.
    # Let's just find the point that is covered by the maximum number of intervals.

    intervals = []
    for k in range(1, max_k):
        intervals.append((L(k), R(k)))

    # Find the maximum number of overlapping intervals.
    # A point x is in the intersection if for all i, L_i < x <= R_i.
    # Since the intervals are (L_i, R_i], we can check the points R_i.
    # For each R_j, count how many intervals (L_i, R_i] contain R_j.
    # That is, how many i satisfy L_i < R_j <= R_i.

    max_overlap = 0
    for j in range(max_k):
        R_j = R(j)
        overlap = 0
        for i in range(max_k):
            if L(i) < R_j <= R(i):
                overlap += 1
        max_overlap = max(max_overlap, overlap)
    return max_overlap

